import { createChatBotMessage } from 'react-chatbot-kit';

class ActionProvider {
  constructor(createChatBotMessage, setStateFunc, createClientMessage, stateRef, createCustomMessage) {
    this.createChatBotMessage = createChatBotMessage;
    this.setState = setStateFunc;
    this.createClientMessage = createClientMessage;
    this.stateRef = stateRef;
    this.createCustomMessage = createCustomMessage;
  }

  handleGetQuote = () => {
    const message = this.createChatBotMessage(
      "I'll help you get a shipping quote! Let me walk you through the process step by step.",
      {
        widget: 'quote',
      }
    );
    this.setState((prev) => ({
      ...prev,
      messages: [...prev.messages, message],
    }));
  };

  handleTrackPackage = () => {
    const message = this.createChatBotMessage(
      "I can help you track your package! Please enter your tracking number below.",
      {
        widget: 'tracking',
      }
    );
    this.setState((prev) => ({
      ...prev,
      messages: [...prev.messages, message],
    }));
  };

  handleDutyQuestion = () => {
    const message = this.createChatBotMessage(
      "📋 **Duties & Taxes Explained:**\n\n" +
      "• **Import Duties**: Calculated based on product category and origin country\n" +
      "• **VAT**: 20% on items over £15 when shipping to UK\n" +
      "• **Handling Fees**: Some carriers charge for customs processing\n\n" +
      "I can calculate exact amounts when you get a quote! Would you like me to help with that?"
    );
    this.setState((prev) => ({
      ...prev,
      messages: [...prev.messages, message],
    }));
  };

  handleCarrierQuestion = () => {
    const message = this.createChatBotMessage(
      "🚛 **Supported Carriers:**\n\n" +
      "• **Express**: UPS, FedEx, DHL\n" +
      "• **Standard**: Royal Mail, USPS, Canada Post\n" +
      "• **Economy**: Hermes, Yodel, DPD\n\n" +
      "I can track packages from any of these carriers automatically. Just paste your tracking number!"
    );
    this.setState((prev) => ({
      ...prev,
      messages: [...prev.messages, message],
    }));
  };

  handleGeneralHelp = () => {
    const message = this.createChatBotMessage(
      "I'm here to help with all your shipping needs! Here's what I can do:",
      {
        widget: 'overview',
      }
    );
    this.setState((prev) => ({
      ...prev,
      messages: [...prev.messages, message],
    }));
  };

  handleDefault = () => {
    const message = this.createChatBotMessage(
      "I'm not sure I understand. Try asking about:\n\n" +
      "• **Shipping quotes** - \"How much to ship to London?\"\n" +
      "• **Package tracking** - \"Track my package\"\n" +
      "• **Duties & taxes** - \"How are duties calculated?\"\n" +
      "• **Carriers** - \"Which carriers do you support?\"\n\n" +
      "Or click the buttons below for quick actions!",
      {
        widget: 'overview',
      }
    );
    this.setState((prev) => ({
      ...prev,
      messages: [...prev.messages, message],
    }));
  };

  updateQuoteData = (field, value) => {
    this.setState((prev) => ({
      ...prev,
      quoteData: {
        ...prev.quoteData,
        [field]: value,
      },
    }));
  };

  updateTrackingData = (field, value) => {
    this.setState((prev) => ({
      ...prev,
      trackingData: {
        ...prev.trackingData,
        [field]: value,
      },
    }));
  };
}

export default ActionProvider; 